const o={en:[{id:1,category:"products",tags:["CHI 2026","UIST 2026 Demo","Generative AI","Spatial computing","XR interaction"],featured:!0,title:"Roomify",description:"Transforming real rooms into themed virtual environments, with spatial layout and physical affordances intact.",year:"2025—2026",members:"Xueyang Wang, Qinxuan Cen, Weitao Bi, Yunxiang Ma",sections:[{title:"Spatially grounded generation",content:"Roomify creates themed VR environments from real rooms. It retains the layout and functional relationships of furniture while changing their visual form. The research asks how generative environments can support immersion without removing a user’s awareness of the physical room.",images:["/images/roomify-head.png"]},{title:"System & interaction",content:`The pipeline combines scene understanding, style reasoning, content generation, and spatial registration. Video SLAM and semantic parsing produce a 3D scaffold; text or image references guide the generation of objects, materials, and surroundings.

I co-designed the system and its XR interaction modules, and integrated an agent workflow using SLAM3R, SpatialLM, image generation, and 3D generation. Creators can inspect a spatial scaffold in MR, edit individual objects, regenerate selected elements, and preview the result in VR.`,images:["/images/roomify-pipeline.png","/images/roomify-mr.png"]},{title:"Evaluation",content:`We evaluated Roomify with 18 VR users and 8 design professionals. Reported immersion increased by 63% over passthrough and 26% over a fully virtual baseline. Design participants rated spatial awareness at 5.95/7 and creative support at 6.08/7.

The work was accepted at CHI 2026. A live demonstration was also accepted for UIST 2026.`,images:["/images/roomify-usertest1.png","/images/roomify-analysis1.png","/images/roomify-usertest2.png","/images/roomify-analysis2.png"]}],links:[{label:"Paper · arXiv",url:"https://doi.org/10.48550/arXiv.2603.04917"},{label:"Code · GitHub",url:"https://github.com/NiceStone-Hill/Virtual_Merge_Generation"}]},{id:2,category:"compdesign",tags:["Data Mining","NLP","Boardgame Design"],featured:!0,title:"Cognitive Tracks",description:"Turning campus movement data and visitors’ accounts into a board game and an AR guide.",year:"2023",members:"Individual project",sections:[{title:"Reading a campus through movement",content:"This individual project studies how people navigate Tsinghua’s campus. GPS traces and social-media posts identify places where visitors pause, the routes they take, and the associations they form. The findings inform a hexagonal board game and a mobile AR guide.",images:["/images/boardgame-flowchart.png"]},{title:"Fieldwork & analysis",content:`Under the supervision of Prof. Weixin Huang, I collected routes from 50 participants in August–September 2023. Python processing used Haversine distance and 60-second mean velocity to clean movement data. Low-speed samples (below 0.674 m/s) provided initial stopping candidates; density filtering and K-means identified 11 representative sites.

Around 200 Xiaohongshu posts contributed word-frequency and affective information. Combining these sources produced maps of visiting density, digital emotion, and physical stopping points.`,images:["/images/boardgame-experiment.png","/images/boardgame-clustering.png"]},{title:"From analysis to play",content:`The board and its components translate route patterns into choices players can make. The AR layer provides location-specific information.

Slower movement sometimes indicated congestion rather than interest, so velocity alone could not explain visitor preferences. Comparing interests in history, architecture, and nature helped distinguish different visiting sequences and dwell patterns.`,images:["/images/boardgame-design.png","/images/boardgame-result.png","/images/boardgame-effect.png"]}],links:[]},{id:3,category:"compdesign",tags:["EEG","Machine Learning","UX Design","Parametric Architecture"],featured:!0,title:"EEG-informed Exhibition Design",description:"Studying emotional responses to audiovisual stimuli and using the findings to inform modular exhibition spaces.",year:"2024—2025",members:"Yunxiang Ma, Yutong Wu",sections:[{title:"From perception to spatial design",content:"This group project connects EEG-based emotion recognition with modular exhibition design. It investigates how visual and auditory stimuli influence emotional response, then uses these findings to propose personalized routes through an exhibition. The work was selected for Tsinghua Architecture’s 2025 undergraduate exhibition.",images:["/images/imagine-experiment.png"]},{title:"Experimental study",content:`Three controlled studies, each with eight participants, compared visual, auditory, and audiovisual conditions. We recorded EEG using a 16-channel OpenBCI device at 256 Hz, with GSR and EMG as supplementary measures. Sessions lasted 15–20 minutes with 15-second stimulus epochs.

Preprocessing included band-pass and 50 Hz notch filtering, ICA artifact rejection, and baseline correction. We extracted power-spectrum and time-domain features, and compared SVM, KNN, and Random Forest classifiers using valence–arousal labels. Random Forest performed best among the tested classifiers.`,images:["/images/imagine-equipment.png","/images/imagine-data.png","/images/imagine-variables.png","/images/imagine-dataframe.png","/images/apparatus.png","/images/imagine-baseline.png","/images/imagine-ml.png"]},{title:"Modular proposal",content:`A 3 × 3 × 3 m prototype translates the study into spatial modules. A shape grammar defines 16 variants with different degrees of publicness, body posture, and circulation. Grasshopper scripts organize their assembly with horizontal and vertical circulation elements.

The proposal uses affect recognition to inform route recommendations. Personalized route recommendations remain a proposal for further evaluation.`,images:["/images/imagine-experience.png","/images/imagine-prototype.png","/images/imagine-shapegrammar.png","/images/imagine-grasshopper.png","/images/imagine-combination.png","/images/imagine-details.png","/images/imagine-final.png"]}],links:[]},{id:4,category:"dataviz",tags:["Urban Analysis","Computer Vision","ML","Clustering"],featured:!0,title:"Colors of Hong Kong",description:"Mapping street-level color patterns along Hong Kong’s Central–Mid-Levels Escalator.",year:"2024",members:"Yunxiang Ma, Jing Zhuang, Tino Zhu",sections:[{title:"A street-level study",content:"The study follows the Central–Mid-Levels Escalator, where commercial, residential, and heritage spaces meet. We examine how street-level color patterns relate to the corridor’s changing urban functions.",images:[]},{title:"Computer vision & clustering",content:"Street-view imagery was collected along the route and segmented with DeepLabV3 into elements such as buildings, trees, signs, pavement, and sky. We extracted color features, converted RGB values to HSV, reduced dimensionality with PCA, and grouped patterns with K-means.",images:["/images/hongkong-data.png","/images/hongkong-extraction.png","/images/hongkong-clustering.png"]},{title:"Color & urban function",content:"Within the sampled route, Central’s office and commercial areas tended toward cooler, less saturated palettes. Residential and mixed-use areas in Mid-Levels showed warmer, more saturated tones. Mapping these clusters provides a way to compare visual character with land use.",images:["/images/hongkong-result.png"]}],links:[]},{id:5,category:"products",tags:["UX Design","Mobile App","Product Design"],featured:!1,title:"Pet’s Tribe",description:"A mobile product concept bringing pet communities, adoption support, and everyday care into one place.",year:"2023",members:"Yunxiang Ma, Yuying Zhang, Xinning He, Rhone Ryan Huang Ern",sections:[{title:"Product question",content:"Pet owners and animal organizations often use separate services for community, adoption, and daily care. Pet’s Tribe explores how these activities could share a consistent mobile experience. Competitor research informed three areas: assistance, community, and a personal diary.",images:[]},{title:"Information architecture",content:"The assistance area supports adoption and care information. Community features organize posts and offline activities. The diary lets owners document daily life with privacy controls. Storyboards connect these features to different user needs and routines.",images:["/images/pet-structure.png","/images/pet-storyboard.png"]},{title:"Prototype & next evaluation",content:"The design progressed from sketches to a high-fidelity Figma prototype covering sign-in, user pathways, community, assistance, and diary screens. Planned usability evaluation would measure task completion, error recovery, and System Usability Scale scores; these are proposed measures, not reported results.",images:["/images/pet-prototype1.png","/images/pet-prototype2.png"]}],links:[]},{id:6,category:"xr",tags:["UX Design","VR","3D Scanning","Unity"],featured:!1,title:"Feeling Home in Memory",description:"Reconstructing a couple’s memories of home through interviews, 3D scanning, and VR.",year:"2024",members:"Individual project",sections:[{title:"Listening to a remembered home",content:"In July 2024, I interviewed a couple in Chongqing about their former and current homes. Their accounts of daily routines, shared spaces, and pets became the basis for an individual VR project about domestic memory.",images:[]},{title:"Interviews, drawings & capture",content:`The couple drew floor plans and traced changes in mood across a day and a year. Two scenes guided the reconstruction: family dinner at dusk in the former home, and reading at night in the current living room.

Mobile 3D scanning captured rooms and furniture. I assembled the scenes in Unity, using interview drawings to guide the selection of objects, light, and atmosphere.`,images:["/images/vr-sketch.png","/images/vr-workflow.png"]},{title:"The VR experience",content:"The final scenes combine scanned objects, generated skyboxes, and recorded soundscapes, including birds, traffic, and pets. Participants can move through the reconstructed rooms in a headset. The project treats personal accounts as design material, attending to the ordinary details that make a place feel like home.",images:["/images/vr-experience.png"]}],links:[]},{id:7,category:"products",tags:["NOVA Most InNOVAtive Prize","AI","Music Generation","Accessibility","Synesthesia","Web App"],featured:!0,title:"SyneSound",description:"A visual music-making interface that maps color, shape, and motion to musical structure.",year:"2025",members:"Yongyi Xiong, Yunxiang Ma",sections:[{title:"Composing through visual choices",content:"Developed by Yongyi Xiong and Yunxiang Ma, SyneSound explores visual composition for people without musical training and for Deaf and hard-of-hearing creators. Users arrange visual elements to specify musical ideas. The project received CMU NOVA’s Most InNOVAtive Prize.",images:["/images/SyneSound 1.png","/images/SyneSound 2.png"]},{title:"Visual-to-musical mapping",content:`Hue maps to modes; solid colors represent notes and blended colors represent chords. Position controls time and register, size sets duration, opacity controls dynamics, and rotation changes chord inversion. Motion encodes tempo, accent, and swing.

React, Konva, and Tone.js support the canvas and local interaction. Agentuity coordinates the generation workflow; OpenAI prepares prompts and MusicGen on Replicate generates audio.`,images:["/images/SyneSound 3.png","/images/SyneSound 4.png"]},{title:"Design intent & open questions",content:"Explicit visual mappings let collaborators discuss musical structure without relying entirely on notation or listening. The proposed next study pairs Deaf and hard-of-hearing composers with hearing audiences to examine whether the intended emotion is preserved in the generated music. Accessibility and emotional correspondence remain questions for evaluation.",images:["/images/SyneSound 5.png","/images/SyneSound 6.png"]}],links:[]},{id:8,category:"xr",tags:["WebXR","Browser AR","Three.js","Procedural Generation","Computer Vision","Serious Play"],featured:!0,title:"DomestiCade",description:"Turning photographs of everyday rooms into playable AR obstacle courses.",year:"2026",members:"Xinyi Li, Yongyi Xiong, Yunxiang Ma",sections:[{title:"A room as a game level",content:"DomestiCade is a browser-based AR platform game. A photograph of the surrounding room supplies objects and surfaces that the system translates into platforms, obstacles, collectibles, and goals. Players choose the scene; computational rules interpret its possibilities for play.",images:[]},{title:"Interpretation & implementation",content:"Computer vision provides semantic information for procedural level rules: a table edge can become a ledge, while a small object can become an obstacle. WebXR registers the resulting level in the physical room. The prototype uses Three.js, Cannon.js physics, serverless vision inference, and local 3D assets.",images:["/images/domesticade-pipeline.png"]},{title:"What the prototype explores",content:"The project examines how machine interpretation can contribute to a spatial game while keeping the player’s choice of place visible in the result. Its procedural rules balance recognizable room structure with navigable, playable geometry.",images:["/images/domesticade-scene.png"]}],links:[]},{id:9,category:"compdesign",tags:["Vision-Language Models","Spatial Reasoning","QLoRA","Qwen2.5-VL","InstaOrder","COCO"],featured:!0,title:"Spatial Depth Reasoning in VLMs",description:"Building a spatial-reasoning dataset and benchmark from public image resources, then fine-tuning and evaluating a 7B vision-language model end to end.",year:"2026",members:"Jingwu Wang, Yongyi Xiong, Yunxiang Ma",sections:[{title:"Building the dataset, not just tuning the model",content:`Our work focused on the complete experimental pipeline: reconstructing a task-specific dataset from public image resources, designing a benchmark, establishing baselines, fine-tuning a model, and analyzing its predictions. We built on COCO 2017 images and existing InstaOrder depth annotations; our contribution was turning those resources into controlled VLM instruction examples and an evaluation workflow.

The task is deliberately narrow: given an image and two localized objects, is Object A in front of or behind Object B? We extracted object pairs, instance masks, bounding boxes, and depth-order labels, preserved instance identity, and rendered images with boxes labeled A and B. This makes the intended pair explicit even when several objects share the same category.`,images:["/images/vlm-depth/dataset-example.png"],imageCaptions:["Final report, Figure 1 (p. 1): the original COCO image and two marked variants with the A/B identities swapped."],zoomImages:!0},{title:"A balanced, image-disjoint benchmark",content:`Each unordered object pair becomes two directional queries, (A, B) and (B, A), with reversed front/behind labels. Every split is therefore exactly balanced: always answering “front” cannot exceed 50% accuracy. We assign all pairs from one source image to a single split, preventing the same image from appearing in both training and evaluation.

The resulting dataset contains 26,046 training queries, 2,746 validation queries, and 2,952 test queries. These counts refer to directional examples, not unique images. We checked sample counts, label balance, image-disjointness, and rendered examples before running the experiments.`,images:[],table:{caption:"Dataset reconstructed from COCO 2017 images and InstaOrder annotations · final report, §2",columns:["Split","Directional queries","Front / behind"],rows:[["Training","26,046","50% / 50%"],["Validation","2,746","50% / 50%"],["Test","2,952","50% / 50%"]]}},{title:"Evaluating relationships and generated explanations",content:`We built a shared prompt, inference, and answer-parsing pipeline. Models generate a short rationale followed by a front/behind answer; the parser maps free-form responses to front, behind, or unknown. Every setting uses the same marked images, underlying pairs, labels, and splits.

Accuracy alone can hide directional guessing. Consistency Score measures whether reciprocal queries produce opposite labels; Pair Accuracy requires both directions to be correct. We also break accuracy down by target label, 2D overlap, and bounding-box IoU. A separate model-judge evaluation scores visual grounding, depth reasoning, and hallucination in the generated rationales. These scores are diagnostic signals, rather than proof that a model reasons correctly.`,images:["/images/vlm-depth/evaluation-metrics.png"],imageCaptions:["Final report, Table 2 (p. 3): evaluation metrics for individual decisions, reciprocal pairs, and generated rationales."],zoomImages:!0},{title:"From zero-shot baselines to QLoRA fine-tuning",content:`Our eight experimental settings compare 7B and 72B zero-shot Qwen2.5-VL baselines, three prompt-only 7B cue variants, and three QLoRA-tuned 7B variants. The spatial cues are bounding-box coordinates, a binary 2D-overlap flag, or both. Holding the data and marked-image inputs fixed lets us distinguish the effect of prompting from the effect of learning to use these cues.

We fine-tuned Qwen2.5-VL-7B with a frozen 4-bit NF4 backbone and trainable low-rank adapters: rank 64, scaling 128, dropout 0.05, bfloat16 computation, a learning rate of 1 × 10⁻⁴, and an effective batch size of 64. Training uses next-token cross-entropy over the generated target response, without a separate binary classification head.

The workflow extends through experiment scripts, distributed inference on Modal, output parsing, metric aggregation, and visualization. Main inference jobs used eight parallel containers with one NVIDIA B200 each. Our contribution is a controlled application and evaluation pipeline, rather than a new fine-tuning algorithm.`,images:["/images/vlm-depth/experiment-configurations.png"],imageCaptions:["Final report, Table 3 (p. 3): all eight configurations, with the same marked-image input throughout."],zoomImages:!0},{title:"The complete results",content:`The strongest configuration, 7B QLoRA with bounding boxes and overlap, achieved 92.65% accuracy, 96.82% consistency, and 91.06% pair accuracy. On this filtered test set, that is 42.14 percentage points above the 7B zero-shot baseline and 22.49 points above the 72B zero-shot reference. All three tuned variants exceeded 91% accuracy.

Prompt-only cues raised 7B accuracy to about 65–66%, but did not produce equally reliable reciprocal decisions. For example, overlap-only prompting reached 65.18% accuracy with 40.81% consistency. Fine-tuning delivered the larger improvement. The full report table below preserves all eight settings, subgroup results, and rationale-quality diagnostics.`,images:["/images/vlm-depth/results-summary.png"],imageCaptions:["Final report, Table 4 (p. 4): full experimental summary. “7B + bbox/ov” columns are QLoRA-tuned; “7B ZS + …” columns use prompting only. ZS = zero-shot; ov = overlap."],zoomImages:!0,table:{caption:"Key comparisons on the same 2,952-query test set",columns:["Model / setting","Accuracy","Consistency","Pair accuracy"],rows:[["7B zero-shot","50.51%","26.15%","21.61%"],["72B zero-shot","70.16%","67.01%","53.66%"],["7B QLoRA · bbox + overlap","92.65%","96.82%","91.06%"]]}},{title:"Reducing directional bias; testing occlusion",content:`The untuned 7B model was near chance overall, but its errors were strongly directional: 74.53% accuracy on front queries versus 26.49% on behind queries. With combined cues and QLoRA, those figures became 93.56% and 91.73%, respectively. The improvement therefore includes a much more balanced decision rule.

Occlusion remains harder. The strongest model reached 96.08% accuracy when the queried boxes did not overlap, but 75.80% when they did. Reporting these slices separately prevents the strong aggregate score from hiding the difficult cases.`,images:["/images/vlm-depth/direction-accuracy.png","/images/vlm-depth/overlap-accuracy.png"],imageCaptions:["Final report, Figure 4 (p. 5): accuracy by front/behind target label.","Final report, Figure 3 (p. 5): accuracy for overlapping and non-overlapping bounding boxes."],zoomImages:!0},{title:"Limits and next steps",content:`Performance also declines in the high-IoU bucket: the best model scored 77.78% when bounding-box IoU exceeded 0.3, compared with 93.08% at IoU = 0. Bounding boxes and a binary overlap flag are not enough to resolve every ambiguous scene.

The combined-cue model received a visual-grounding score of 4.80/5 and a 3.3% hallucination rate from the rationale judge, but the strongest evidence remains the decision and reciprocal-pair metrics. We have not established transfer to broader spatial benchmarks or verified that this specialized tuning preserves general VLM capabilities. Future work should test both, and explore richer visibility cues such as segmentation masks, visible-area ratios, relative scale, and depth-order priors.`,images:["/images/vlm-depth/iou-accuracy.png"],imageCaptions:["Final report, Figure 5 (p. 5): accuracy across bounding-box IoU buckets, showing the remaining difficulty of high-overlap cases."],zoomImages:!0}],links:[{label:"Code · GitHub",url:"https://github.com/yongyi2002/10623_project"}]}],zh:[{id:1,category:"products",tags:["CHI 2026","UIST 2026 Demo","Generative AI","Spatial computing","XR interaction"],featured:!0,title:"Roomify",description:"将真实房间转化为主题化虚拟环境，同时保留空间布局与实体物件的使用方式。",year:"2025—2026",members:"Xueyang Wang, Qinxuan Cen, Weitao Bi, Yunxiang Ma",sections:[{title:"以真实空间为基础的生成",content:"Roomify 基于真实房间生成主题化 VR 环境，在改变视觉形态的同时保留家具布局与功能关系。研究关注生成式环境如何增强沉浸感，同时维持用户对物理空间的感知。",images:["/images/roomify-head.png"]},{title:"系统与交互",content:`系统由场景理解、风格推理、内容生成与空间配准四个阶段组成。视频 SLAM 与语义解析构建三维框架，文本或图像参考引导物体、材质及环境生成。

我参与系统与 XR 交互模块设计，整合了 SLAM3R、SpatialLM、图像生成和三维生成的智能体工作流。创作者可以在 MR 中查看空间框架、编辑物体、局部重新生成，并在 VR 中预览结果。`,images:["/images/roomify-pipeline.png","/images/roomify-mr.png"]},{title:"评估",content:`研究邀请 18 名 VR 用户和 8 名设计专业人士参与评估。报告的沉浸感相较透视基线提高 63%，相较全虚拟基线提高 26%。设计参与者对空间感知与创作支持的评分分别为 5.95/7 和 6.08/7。

研究获 CHI 2026 录用，现场演示获 UIST 2026 Demos 录用。`,images:["/images/roomify-usertest1.png","/images/roomify-analysis1.png","/images/roomify-usertest2.png","/images/roomify-analysis2.png"]}],links:[{label:"Paper · arXiv",url:"https://doi.org/10.48550/arXiv.2603.04917"},{label:"Code · GitHub",url:"https://github.com/NiceStone-Hill/Virtual_Merge_Generation"}]},{id:2,category:"compdesign",tags:["Data Mining","NLP","Boardgame Design"],featured:!0,title:"Cognitive Tracks",description:"将校园行动轨迹与访客叙述转化为桌游及 AR 导览。",year:"2023",members:"独立项目",sections:[{title:"从行动轨迹理解校园",content:"这项独立研究以清华校园为场地，结合 GPS 轨迹与社交媒体文本，分析访客的停留位置、路径选择及地点印象，并将结果转化为六边形桌游和移动 AR 导览。",images:["/images/boardgame-flowchart.png"]},{title:"调研与分析",content:`在黄蔚欣教授指导下，我于 2023 年 8—9 月采集了 50 位参与者的游览轨迹。使用 Python、Haversine 距离与 60 秒平均速度清洗数据，以低于 0.674 m/s 的低速样本筛选停留候选点，经密度过滤与 K-means 聚类提取 11 处代表性地点。

约 200 篇小红书帖子提供词频与情感信息。两类数据共同构成游览密度图、数字情感图与物理停留点地图。`,images:["/images/boardgame-experiment.png","/images/boardgame-clustering.png"]},{title:"从分析到游戏",content:`桌游棋盘与组件将路径模式转化为玩家可以选择的行动，AR 图层补充与地点相关的信息。

低速有时来自拥堵，而非吸引力，因此不能仅凭速度解释偏好。对历史、建筑和自然等不同兴趣群体进行比较，有助于区分游览顺序与停留模式。`,images:["/images/boardgame-design.png","/images/boardgame-result.png","/images/boardgame-effect.png"]}],links:[]},{id:3,category:"compdesign",tags:["EEG","Machine Learning","UX Design","Parametric Architecture"],featured:!0,title:"EEG 驱动的展览设计",description:"研究视听刺激下的情绪反应，并据此设计模块化展览空间。",year:"2024—2025",members:"Yunxiang Ma, Yutong Wu",sections:[{title:"从感知研究到空间设计",content:"项目将基于 EEG 的情绪识别与模块化展览设计结合，研究视觉和听觉刺激对情绪反应的影响，并据此提出个性化参观路径。作品入选清华大学建筑学院 2025 年本科毕业展。",images:["/images/imagine-experiment.png"]},{title:"实验研究",content:`三组受控实验各邀请 8 位参与者，对比视觉、听觉及视听融合条件。采用 16 通道 OpenBCI，以 256 Hz 采样，并辅以 GSR 与 EMG。每次实验持续 15—20 分钟，单个刺激时段为 15 秒。

预处理包括带通与 50 Hz 陷波、ICA 伪迹剔除和基线校正。提取功率谱及时间域特征，以效价—唤醒度标注比较 SVM、KNN 与随机森林，随机森林在测试模型中表现最佳。`,images:["/images/imagine-equipment.png","/images/imagine-data.png","/images/imagine-variables.png","/images/imagine-dataframe.png","/images/apparatus.png","/images/imagine-baseline.png","/images/imagine-ml.png"]},{title:"模块化空间方案",content:`方案以 3 × 3 × 3 m 空间原型转译实验结果，通过形态文法定义 16 种在公共性、身体姿态及流线方面不同的变体。Grasshopper 脚本组织模块与水平、垂直交通单元的拼装。

方案提出依据情绪识别推荐参观路径。个性化路径推荐仍属于有待进一步评估的设计方案。`,images:["/images/imagine-experience.png","/images/imagine-prototype.png","/images/imagine-shapegrammar.png","/images/imagine-grasshopper.png","/images/imagine-combination.png","/images/imagine-details.png","/images/imagine-final.png"]}],links:[]},{id:4,category:"dataviz",tags:["Urban Analysis","Computer Vision","ML","Clustering"],featured:!0,title:"香港的城市色彩",description:"沿香港中环至半山扶梯，识别并绘制街道色彩模式。",year:"2024",members:"Yunxiang Ma, Jing Zhuang, Tino Zhu",sections:[{title:"街道尺度的研究",content:"研究以中环至半山扶梯为线索，观察商业、住宅与历史空间相遇的街道，分析沿线色彩模式与城市功能变化的关系。",images:[]},{title:"计算机视觉与聚类",content:"沿线采集街景图像，用 DeepLabV3 识别建筑、树木、标识、铺地及天空等要素。提取色彩特征，将 RGB 转换为 HSV，经 PCA 降维后使用 K-means 对色彩模式聚类。",images:["/images/hongkong-data.png","/images/hongkong-extraction.png","/images/hongkong-clustering.png"]},{title:"色彩与城市功能",content:"在所采集的街段中，中环办公与商业片区较多呈现冷色、低饱和度的组合；半山住宅及混合功能区则更偏暖色、较高饱和度。将聚类结果映射回街道，可以对照视觉特征与土地使用。",images:["/images/hongkong-result.png"]}],links:[]},{id:5,category:"products",tags:["UX Design","Mobile App","Product Design"],featured:!1,title:"Pet’s Tribe",description:"整合宠物社区、领养协助与日常记录的移动产品概念。",year:"2023",members:"Yunxiang Ma, Yuying Zhang, Xinning He, Rhone Ryan Huang Ern",sections:[{title:"产品问题",content:"宠物主人与动物组织常需分别使用社区、领养及日常照护服务。Pet’s Tribe 研究如何将这些活动整合为一致的移动体验，竞品分析形成协助、社区与个人日记三个方向。",images:[]},{title:"信息架构",content:"协助模块组织领养流程与照护信息，社区模块承载帖子与线下活动，日记模块用于记录日常并设置可见范围。故事板将这些功能与不同用户的需求和习惯联系起来。",images:["/images/pet-structure.png","/images/pet-storyboard.png"]},{title:"原型与后续评估",content:"设计从草图发展为 Figma 高保真原型，涵盖登录、用户分流、社区、协助与日记。后续可用性评估计划关注任务完成率、错误恢复及 SUS 评分；这些是拟采用的指标，并非已完成的测试结果。",images:["/images/pet-prototype1.png","/images/pet-prototype2.png"]}],links:[]},{id:6,category:"xr",tags:["UX Design","VR","3D Scanning","Unity"],featured:!1,title:"Feeling Home in Memory",description:"通过访谈、三维扫描与 VR，重建一对夫妇关于家的记忆。",year:"2024",members:"独立项目",sections:[{title:"倾听关于家的记忆",content:"2024 年 7 月，我在重庆采访一对夫妇，了解他们对旧居与现居的记忆。他们讲述的日常习惯、共同使用的空间及宠物，构成了这项居住记忆 VR 项目的基础。",images:[]},{title:"访谈、绘图与扫描",content:`受访者绘制平面图，并记录一天及一年中的情绪变化。两个场景成为重建重点：旧居黄昏时的家庭晚餐，以及现居客厅里的夜间阅读。

通过移动三维扫描采集房间与家具，在 Unity 中重建场景，并依据访谈图纸选择物件、光线与环境氛围。`,images:["/images/vr-sketch.png","/images/vr-workflow.png"]},{title:"VR 体验",content:"最终场景结合扫描物件、生成式天空盒与鸟鸣、交通、宠物等实录声音。体验者可以佩戴头显在重建的房间中行走。项目将个人叙述作为设计材料，关注让人产生归属感的日常细节。",images:["/images/vr-experience.png"]}],links:[]},{id:7,category:"products",tags:["NOVA Most InNOVAtive Prize","AI","Music Generation","Accessibility","Synesthesia","Web App"],featured:!0,title:"SyneSound",description:"将颜色、形状与运动映射为音乐结构的可视化创作界面。",year:"2025",members:"Yongyi Xiong, Yunxiang Ma",sections:[{title:"以视觉选择创作音乐",content:"SyneSound 由 Yongyi Xiong 与 Yunxiang Ma 合作开发，面向缺少音乐训练的人群及聋人、重听创作者，探索通过编排视觉元素表达音乐想法。项目获得 CMU NOVA Most InNOVAtive Prize。",images:["/images/SyneSound 1.png","/images/SyneSound 2.png"]},{title:"视觉与音乐的映射",content:`色相对应调式，纯色代表单音，混色代表和弦。位置控制时间与音区，尺寸设置时值，透明度控制力度，旋转改变和弦转位，运动表达速度、重音与摇摆节奏。

React、Konva 与 Tone.js 支持画布和本地交互；Agentuity 协调生成流程，OpenAI 处理提示词，Replicate 上的 MusicGen 生成音频。`,images:["/images/SyneSound 3.png","/images/SyneSound 4.png"]},{title:"设计意图与待研究问题",content:"明确的视觉映射帮助协作者讨论音乐结构，减少对乐谱及聆听的依赖。后续拟邀请聋人、重听创作者与健听听众共同评估，检验生成音乐是否保留创作时的情绪意图。无障碍效果与情绪对应关系仍需进一步验证。",images:["/images/SyneSound 5.png","/images/SyneSound 6.png"]}],links:[]},{id:8,category:"xr",tags:["WebXR","Browser AR","Three.js","Procedural Generation","Computer Vision","Serious Play"],featured:!0,title:"DomestiCade",description:"将日常房间的照片转化为可游玩的 AR 障碍关卡。",year:"2026",members:"Xinyi Li, Yongyi Xiong, Yunxiang Ma",sections:[{title:"将房间理解为游戏关卡",content:"DomestiCade 是一款基于浏览器的 AR 平台游戏。用户拍摄周围房间，系统将其中的物体与表面转译为平台、障碍、收集物及目标。玩家选择场景，计算规则解析可用于游戏的空间结构。",images:[]},{title:"场景转译与实现",content:"计算机视觉为程序化关卡规则提供语义信息，例如将桌面边缘转为平台、小型物体转为障碍。WebXR 将生成关卡配准到真实房间。原型使用 Three.js、Cannon.js 物理引擎、无服务器视觉推理与本地三维素材。",images:["/images/domesticade-pipeline.png"]},{title:"原型探索的问题",content:"项目研究机器解释如何参与空间游戏设计，并在结果中保留玩家所选择场所的特征。程序化规则在可识别的房间结构与便于行动、游玩的几何关系之间进行协调。",images:["/images/domesticade-scene.png"]}],links:[]},{id:9,category:"compdesign",tags:["Vision-Language Models","Spatial Reasoning","QLoRA","Qwen2.5-VL","InstaOrder","COCO"],featured:!0,title:"视觉语言模型的空间深度推理",description:"基于公开图像资源重构空间推理数据集与 benchmark，完成 7B 视觉语言模型从基线评估到微调、实验分析的全流程。",year:"2026",members:"Jingwu Wang, Yongyi Xiong, Yunxiang Ma",sections:[{title:"从公开资源到自建数据集",content:`我们的工作重点是完整实验流程：基于公开图像资源重构任务数据集，设计 benchmark，建立基线，微调模型，并分析预测结果。我们使用 COCO 2017 图像和已有的 InstaOrder 深度标注；核心贡献是将这些资源整理为受控的 VLM 指令样本，并建立相应评测流程。

任务聚焦一个具体问题：给定图像与两个定位后的物体，A 位于 B 的前方还是后方？我们从原始标注中提取物体对、实例掩码、边界框与前后关系标签，保留实例身份，并在图像中绘制标记为 A、B 的边界框。即使同一类别出现多个物体，模型也能明确当前要判断的是哪一对。`,images:["/images/vlm-depth/dataset-example.png"],imageCaptions:["最终报告图 1，第 1 页：COCO 原始图像，以及交换 A/B 身份后的两种标记图像。"],zoomImages:!0},{title:"构建方向平衡、图像互斥的 benchmark",content:`每个无序物体对生成两条方向相反的查询：(A, B) 和 (B, A)，同时翻转 front/behind 标签。因此，每个数据划分的前后标签都严格各占 50%，始终回答“前方”的策略无法超过 50% 准确率。来自同一源图像的所有物体对只进入一个划分，避免训练与评估之间出现图像泄漏。

最终得到 26,046 条训练样本、2,746 条验证样本和 2,952 条测试样本。这里统计的是带方向的查询样本，而非独立图像数。实验前，我们检查样本数量、标签平衡、图像互斥性，并人工核查标记图像。`,images:[],table:{caption:"基于 COCO 2017 与 InstaOrder 重构的数据划分 · 最终报告第 2 节",columns:["数据划分","带方向的查询样本","前方 / 后方"],rows:[["训练集","26,046","50% / 50%"],["验证集","2,746","50% / 50%"],["测试集","2,952","50% / 50%"]]}},{title:"同时评估关系判断与生成式解释",content:`我们搭建统一的提示词、推理与答案解析流程。模型先生成简短理由，再给出前后关系结论；解析器将自由文本映射为 front、behind 或 unknown。所有实验使用相同的标记图像、物体对、标签和数据划分。

仅看准确率容易掩盖方向性猜测。一致性指标检查同一物体对的两次反向查询是否给出相反标签；成对准确率则要求两个方向都回答正确。我们还按前后标签、二维重叠情况和边界框 IoU 分组分析。另一个模型作为评审，对生成理由的视觉依据、深度推理与幻觉进行评分；这些评分用于诊断，不等同于对正确推理的证明。`,images:["/images/vlm-depth/evaluation-metrics.png"],imageCaptions:["最终报告表 2，第 3 页：覆盖单次判断、反向查询与生成理由的评测指标。"],zoomImages:!0},{title:"从零样本基线到 QLoRA 微调",content:`我们设计八组实验：7B 与 72B Qwen2.5-VL 零样本基线、三种仅在提示词中加入空间线索的 7B 变体，以及三种经过 QLoRA 微调的 7B 变体。空间线索分别为边界框坐标、二维重叠标记，以及二者组合。固定数据与标记图像输入，使实验能够区分“提供线索”和“训练模型使用线索”的作用。

微调使用冻结的 4-bit NF4 骨干网络和可训练低秩适配器：rank 为 64、scaling 为 128、dropout 为 0.05、bfloat16 计算、学习率为 1 × 10⁻⁴，有效 batch size 为 64。训练目标是生成式回答的 next-token 交叉熵，而非增加独立的二分类头。

全流程还包括实验脚本、Modal 分布式推理、输出解析、指标汇总与可视化。主要推理任务使用八个并行容器，每个容器配备一张 NVIDIA B200。项目贡献在于受控的任务应用和评测流程，而非提出新的微调算法。`,images:["/images/vlm-depth/experiment-configurations.png"],imageCaptions:["最终报告表 3，第 3 页：八组实验配置均使用相同的标记图像输入。"],zoomImages:!0},{title:"完整实验数据汇总",content:`最佳配置为“7B QLoRA + 边界框 + 重叠线索”，达到 92.65% 准确率、96.82% 一致性和 91.06% 成对准确率。在这个筛选后的测试集上，准确率比 7B 零样本基线高 42.14 个百分点，比 72B 零样本参照高 22.49 个百分点。三种微调配置的准确率均超过 91%。

仅增加提示线索能够将 7B 准确率提升至约 65–66%，但反向查询仍不够稳定。例如，仅增加重叠提示时，准确率为 65.18%，一致性却只有 40.81%。微调带来了更显著的提升。下方原始汇总表保留全部八种配置、分组结果和理由质量指标，便于完整比较。`,images:["/images/vlm-depth/results-summary.png"],imageCaptions:["最终报告表 4，第 4 页：完整实验汇总。“7B + bbox/ov”为 QLoRA 微调模型；“7B ZS + …”仅增加提示线索。ZS 表示零样本，ov 表示重叠线索。"],zoomImages:!0,table:{caption:"同一组 2,952 条测试查询上的关键对比",columns:["模型 / 配置","准确率","一致性","成对准确率"],rows:[["7B 零样本","50.51%","26.15%","21.61%"],["72B 零样本","70.16%","67.01%","53.66%"],["7B QLoRA · 边界框 + 重叠","92.65%","96.82%","91.06%"]]}},{title:"方向偏差与遮挡分析",content:`未微调的 7B 模型总体接近随机水平，但错误具有明显方向性：前方标签准确率为 74.53%，后方标签仅为 26.49%。经过组合线索微调后，两者分别达到 93.56% 和 91.73%。因此，改进不仅体现在总分上，也体现在更平衡的关系判断上。

遮挡仍然更难。最佳模型在边界框不重叠时达到 96.08%，重叠时降至 75.80%。单独呈现这些分组，可以避免较高的总体准确率掩盖困难样本。`,images:["/images/vlm-depth/direction-accuracy.png","/images/vlm-depth/overlap-accuracy.png"],imageCaptions:["最终报告图 4，第 5 页：按 front/behind 目标标签划分的准确率。","最终报告图 3，第 5 页：边界框重叠与不重叠条件下的准确率。"],zoomImages:!0},{title:"局限与下一步",content:`高 IoU 分组同样存在性能下降：最佳模型在边界框 IoU 大于 0.3 时的准确率为 77.78%，IoU 为 0 时为 93.08%。边界框和二元重叠标记仍不足以解决所有视觉歧义。

组合线索模型的评审结果为视觉依据 4.80/5、幻觉率 3.3%；但最有力的证据仍是判断准确率和反向查询指标。我们尚未验证结果能否迁移到更广泛的空间 benchmark，也未确认专项微调是否保留了模型原有的通用能力。后续工作应检验这两点，并探索分割掩码、可见面积比例、相对尺度和深度顺序先验等更丰富的线索。`,images:["/images/vlm-depth/iou-accuracy.png"],imageCaptions:["最终报告图 5，第 5 页：按边界框 IoU 分组的准确率，显示高重叠样本仍然较难。"],zoomImages:!0}],links:[{label:"Code · GitHub",url:"https://github.com/yongyi2002/10623_project"}]}]},e=[1,9,7,8,6,3,2,4,5],r={1:"/images/roomify-main.png",2:"/images/boardgame-head.png",3:"/images/imagine-head.png",4:"/images/hongkong-head.png",5:"/images/pet-head.png",6:"/images/vr-head.png",7:"/images/SyneSound 1.png",8:"/images/domesticade-heroimage.png",9:"/images/VLMFT-method.png"},g={1:{en:"Generative environments, grounded in real space.",zh:"以真实空间为基础的生成式虚拟环境。",recognition:"CHI 2026 · UIST 2026 Demo"},9:{en:"A custom depth benchmark, from public data to model tuning.",zh:"从公开数据到自建深度评测基准与模型微调。",image:"/images/VLMFT-img.png",fit:"contain"},7:{en:"Making music through color, shape, and motion.",zh:"用色彩、形状与动作创作音乐。",image:"/images/SyneSound 6.png",recognition:"NOVA Most InNOVAtive Prize"},8:{en:"Everyday rooms become playable AR worlds.",zh:"将日常房间变成可玩的 AR 世界。"},6:{en:"Reconstructing memories of home in virtual reality.",zh:"在虚拟现实中重建关于家的记忆。"},3:{en:"From emotional responses to exhibition spaces.",zh:"从情绪感知到展览空间设计。"},2:{en:"Campus movement translated into a game and AR guide.",zh:"将校园行为数据转化为桌游与 AR 导览。"},4:{en:"Reading a city through its street-level colors.",zh:"通过街道色彩，观察与理解城市。"},5:{en:"A place for pet communities, adoption, and care.",zh:"连接宠物社群、领养与日常照护。"}},c=[{id:"all",en:"All work",zh:"全部",ids:null},{id:"products",en:"Products",zh:"产品",ids:[1,5,7]},{id:"compdesign",en:"Computational design",zh:"计算设计",ids:[2,3,9]},{id:"dataviz",en:"Data & cities",zh:"数据与城市",ids:[4]},{id:"xr",en:"Spatial experiences",zh:"空间体验",ids:[1,6,8]}];function m(a){return[...a].sort((t,s)=>{const n=i=>e.includes(i)?e.indexOf(i):e.length;return n(t.id)-n(s.id)})}export{g as a,r as b,o as c,m as o,c as p};
